// In app/page.tsx im return-Block:
{activeTab === 'inventory' ? (
  <>
    <StatsCards items={items} />
    <InventoryTable
      items={items}
      onUpdateStock={handleUpdateStock}
      onDeleteItem={handleDeleteItem}
      onEditItem={(item) => {
        setSelectedItem(item);
        setIsModalOpen(true);
      }}
      onOpenAddModal={() => {
        setSelectedItem(null);
        setIsModalOpen(true);
      }}
    />
  </>
) : (
  <CategoryView
    items={items}
    onUpdateStock={handleUpdateStock}
    onDeleteItem={handleDeleteItem}
    onEditItem={(item) => {
      setSelectedItem(item);
      setIsModalOpen(true);
    }}
    onOpenAddModal={() => {
      setSelectedItem(null);
      setIsModalOpen(true);
    }}
  />
)}